def solve():
    n, k = map(int, input().split())
    grid = [input() for _ in range(3)]

    start_col = 0
    start_row = -1
    for r in range(3):
        for c in range(n):
            if grid[r][c] == 's':
                start_row = r
                break
        if start_row != -1:
            break


    def is_safe(row, col):
        return 0 <= row < 3 and 0 <= col < n

    def check_collision(row, col, trains):
        for train in trains:
            for r, c in train:
                if r == row and c == col:
                    return True
        return False

    def get_trains(grid):
        trains = []
        for r in range(3):
            train = []
            i = 0
            while i < n:
                if grid[r][i] != '.' and grid[r][i] != 's':
                    char = grid[r][i]
                    j = i
                    while j < n and grid[r][j] == char:
                        train.append((r, j))
                        j += 1
                    trains.append(train)
                    i = j
                else:
                    i += 1
        return trains

    trains = get_trains(grid)

    q = [(start_col, start_row)]
    visited = set()
    visited.add((start_col, start_row))

    while q:
        col, row = q.pop(0)

        if col == n - 1:
            return "YES"









        #Possible moves
        moves = [(col + 1, row - 1), (col + 1, row), (col + 1, row + 1)]

        for next_col, next_row in moves:
            if is_safe(next_row, next_col):


                #Move trains
                new_trains = []
                for train in trains:
                    new_train = []
                    for r, c in train:
