def solve():
    n = int(input())
    fragments = []
    for _ in range(n):
        fragments.append(input())

    def overlap(s1, s2):
        max_overlap = 0
        for i in range(1, min(len(s1), len(s2)) + 1):
            if s1[-i:] == s2[:i]:
                max_overlap = i
        return max_overlap

    def merge(s1, s2):
        o = overlap(s1, s2)
        return s1 + s2[o:]

    while len(fragments) > 1:
        best_i, best_j, max_o = -1, -1, -1
        for i in range(len(fragments)):
            for j in range(len(fragments)):
                if i != j:
                    o = overlap(fragments[i], fragments[j])
                    if o > max_o:
                        max_o = o
                        best_i, best_j = i, j

        if best_i == -1:
            break

        merged_string = merge(fragments[best_i], fragments[best_j])
        fragments.pop(max(best_i, best_j))
        fragments.pop(min(best_i, best_j))
        fragments.append(merged_string)

