        return "0" * digits
    base7 = ""
    while num > 0:
        base7 = str(num % 7) + base7
        num //= 7
    return "0" * (digits - len(base7)) + base7

def solve():
    n, m = map(int, input().split())
    digits_hours = math.ceil(math.log7(n))
    digits_minutes = math.ceil(math.log7(m))

    count = 0
    for hour in range(n):
        for minute in range(m):
            hour_base7 = convert_to_base7(hour, digits_hours)
            minute_base7 = convert_to_base7(minute, digits_minutes)
            combined_digits = hour_base7 + minute_base7
            if len(set(combined_digits)) == len(combined_digits):
                count += 1
    print(count)

solve()

