def format_number(number):
    sign = ""
    if number.startswith("-"):
        sign = "-"
        number = number[1:]

    if "." in number:
        integer_part, fractional_part = number.split(".")
    else:
        integer_part = number
        fractional_part = ""

    # Format integer part
    integer_part = integer_part[::-1]
    formatted_integer = ""
    for i in range(len(integer_part)):
        formatted_integer += integer_part[i]
        if (i + 1) % 3 == 0 and i != len(integer_part) - 1:
            formatted_integer += ","
    formatted_integer = formatted_integer[::-1]

    # Format fractional part
    if not fractional_part:
        fractional_part = "00"
    else:
        fractional_part = fractional_part[:2]
        while len(fractional_part) < 2:
            fractional_part += "0"

    # Combine and add dollar sign
    if sign == "-":
        result = "($" + formatted_integer + "." + fractional_part + ")"
    else:
        result = "$" + formatted_integer + "." + fractional_part

    return result

