        if height < 1 or height > n:
            return False

        if wall == 0:
            if left_wall[height - 1] == 'X':
                return False
        else:
            if right_wall[height - 1] == 'X':
                return False

        if height <= time:
            return False

        return True

    q = [(0, 1, 0)]  # (wall, height, time)
    visited = set()
    visited.add((0, 1, 0))

    while q:
        wall, height, time = q.pop(0)

        if height > n:
            print("YES")
            return

        # Move up
        new_height = min(height + 1, n)
        if is_valid(wall, new_height, time + 1) and (wall, new_height, time + 1) not in visited:
            q.append((wall, new_height, time + 1))
            visited.add((wall, new_height, time + 1))

        # Move down
        new_height = max(height - 1, 1)
        if is_valid(wall, new_height, time + 1) and (wall, new_height, time + 1) not in visited:
            q.append((wall, new_height, time + 1))
            visited.add((wall, new_height, time + 1))

        # Jump to opposite wall
