def isPrime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def nextPrime(n):
    n += 1
    while not isPrime(n):
        n += 1
    return n

def calculateRowMoves(matrix, row_index):
    moves = 0
    for j in range(len(matrix[0])):
        if not isPrime(matrix[row_index][j]):
            moves += nextPrime(matrix[row_index][j]) - matrix[row_index][j]
    return moves

def calculateColMoves(matrix, col_index):
    moves = 0
    for i in range(len(matrix)):
        if not isPrime(matrix[i][col_index]):
            moves += nextPrime(matrix[i][col_index]) - matrix[i][col_index]
    return moves

def isPrimeMatrix(matrix):
