    def traverse(main_courses, visited, course_order):
        if not main_courses:
            return course_order

        course_to_take = main_courses.pop()

        if reqs[course_to_take] is None:
            course_order.append(course_to_take)
            return course_order

        stack = [course_to_take]

        while stack:
            current_course = stack.pop()

            if reqs[current_course] is not None:
                dependencies = reqs[current_course]

                if not dependencies:
                    course_order.append(current_course)
                    reqs[current_course] = None
                else:

                    for dependency in dependencies:
                        if dependency in visited:
                            return []  # Cycle detected

                        visited.add(dependency)
                        stack.append(dependency)

                    stack.append(current_course)  # Add back to stack after adding dependencies
                    reqs[current_course] = []

        return course_order

    visited = set()
    course_order = []

    result = traverse(main_courses.copy(), visited, course_order)

