def neg_direction(d): return (-d[0], -d[1])

def increase_pos(d, pos):
    p = (pos[0] + d[0], pos[1] + d[1])
    if p[0] < 0 or p[1] < 0 or p[0] == n or p[1] == m or road[p[0]][p[1]] == '*':
