            if num not in multiset:
                multiset[num] = 0
            multiset[num] += 1
        elif type == '-':
            num = int(query[1])
            multiset[num] -= 1
        elif type == '?':
            pattern = query[1]
            count = 0
            for num, freq in multiset.items():
