        if (i, f, h, is_footman) in dp:
            return dp[(i, f, h, is_footman)]
        return 0

    def set_dp(i, f, h, is_footman, val):
        dp[(i, f, h, is_footman)] = val

    set_dp(0, 0, 0, 0, 1)

    for i in range(n1 + n2):
        for f in range(k1 + 1):
            for h in range(k2 + 1):
