def calculate_days(x_value, a_values, b_values):
    """Calculates the total number of days the voyage takes for a given x."""
    total_days = 0
    for a, b in zip(a_values, b_values):
        suitcases = a * x_value
        days = 0
        while suitcases > 0:
            days += 1
            suitcases -= b
            if suitcases < 0:
                break
        total_days += days
    return total_days

def solve():
    n, total_days = map(int, input().split())
    a_values = []
    b_values = []
    for _ in range(n):
        a, b = map(int, input().split())
        a_values.append(a)
        b_values.append(b)

    if max(a_values) == 0:
        if n == 1:
            print(0)
        else:
            print(-1)
        return

    left = 1
    right = 10**9 + 1

    ans = -1

    while left <= right:
        mid = (left + right) // 2
        days = calculate_days(mid, a_values, b_values)

        if days == total_days:
            ans = mid
            right = mid -1
        elif days < total_days:
            left = mid + 1
        else:
            right = mid - 1

    if ans == -1:
      print(0)
    else:
      print(ans)
