def normalize_rational(num,den):
    #associate the -ve with the num or cancel -ve sign when both are -ve
    if num ^ den < 0 and num > 0 or num ^ den > 0 and num < 0:
        num = -num; den = -den
    #put it in its simplest form
    g = gcd(abs(num),abs(den))
    num //= g; den //=g
    return (num,den)

