    q = list(map(int, input().split()))
    s = list(map(int, input().split()))

    def apply_q(p):
        result = [0] * n
        for i in range(n):
            result[i] = p[q[i] - 1]
        return result

    def apply_inverse_q(p):
        result = [0] * n
        inverse_q = [0] * n
        for i in range(n):
            inverse_q[q[i] - 1] = i + 1
        for i in range(n):
            result[i] = p[inverse_q[i] - 1]
        return result

    def check(moves):
        current = list(range(1, n + 1))
        history = [current]
        for move in moves:
            if move == 'H':
                current = apply_q(current)
            else:
                current = apply_inverse_q(current)
            history.append(current)

        if current == s:
            if s not in history[:-1]:
                return True
            else:
                return False
