def restore_ipv6(short_address):
    blocks = short_address.split(":")

    num_blocks = len(blocks)

    double_colon_index = -1
    try:
        double_colon_index = blocks.index('')
    except ValueError:
        pass

    if double_colon_index != -1:
        num_zero_blocks = 8 - num_blocks + 1

