            else:
                if(flush == 1):
                    print('{} {} {}'.format(row, K - right[row] + 1 , K - right[row] + size))
                    right[row] -= size
                else:
                    return size * abs(row - mid) + (mid - right[row] - 1) * size + size * (size + 1) // 2
